  ('course', 'service', $json${"title":"Service Quality: From Good to Great","category":"Service Quality","description":"Ubah insight quality assurance menjadi perbaikan layanan yang konsisten.","color":"lavender","level":"Intermediate","art":"quality","lessons":[{"id":"service-m1","title":"Fondasi kualitas layanan","duration":10,"intro":"Kualitas layanan dibangun dari akurasi, kejelasan, empati, dan konsistensi.","sections":[{"heading":"Gunakan bukti yang spesifik","body":"Nilai perilaku yang terlihat pada percakapan. Hubungkan feedback dengan contoh agar agent memahami apa yang perlu dipertahankan atau diperbaiki."},{"heading":"Ikuti standar tim","body":"Gunakan rubric QA yang telah disetujui tim. Materi demo ini tidak menggantikan rubric atau kebijakan internal."}]},{"id":"service-m2","title":"Menemukan akar masalah","duration":10,"intro":"Temukan penyebab di balik pola kesalahan, bukan hanya gejalanya.","sections":[{"heading":"Periksa konteks","body":"Kesalahan dapat terkait pemahaman, akses informasi, kejelasan proses, atau kapasitas kerja. Bandingkan beberapa contoh sebelum menarik kesimpulan."},{"heading":"Tentukan langkah perbaikan","body":"Pilih tindakan yang sesuai dengan penyebab dan tentukan cara memeriksa hasilnya."}]},{"id":"service-m3","title":"Coaching berbasis data","duration":10,"intro":"Coaching membantu agent memahami kesenjangan dan berlatih perilaku yang lebih efektif.","sections":[{"heading":"Bahas satu prioritas","body":"Mulai dari contoh nyata, dengarkan perspektif agent, lalu sepakati target perilaku yang dapat diamati."},{"heading":"Tindak lanjuti","body":"Tetapkan waktu evaluasi dan cek sampel baru. Berikan penguatan untuk perubahan yang sudah terlihat."}]},{"id":"service-m4","title":"Membangun improvement plan","duration":10,"intro":"Rencana perbaikan membuat tujuan, tindakan, dan evaluasi menjadi jelas.","sections":[{"heading":"Buat rencana sederhana","body":"Tulis masalah, bukti, target, tindakan, penanggung jawab, dan tanggal evaluasi